import json
import subprocess
from pathlib import Path

base = Path(__file__).resolve().parent.relative_to(Path.cwd())
landscape = 'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_PHYSIK.de.json'
provider = 'OpenAI / Codex image_gen; precise force diagram rendered from SVG'
specs = {
 'B': ('6ba20688-8cbf-5db1-bda8-346893798d2f', 'Ein Wagen trägt zwei kollineare Kraftpfeile vom selben Punkt: 6 N nach rechts und 4 N nach links. Der Kraftmaßstab zeigt 2 N je Bezugsstrich. Die Resultierende beträgt bei positiver Richtung rechts +2 N. Die Nullsumme passt zu Ruhe und konstanter Geschwindigkeit.'),
 'G': ('77b44d13-4368-5950-a943-decb377c7302', 'Ein Körper berührt eine geneigte Ebene. Der am Körper beginnende Gewichtspfeil von 40 N wird maßstäblich in 20 N parallel zur Ebene und rund 34,6 N senkrecht zu ihr zerlegt. Alle drei Pfeile beginnen am Körper; gestrichelte Parallelen sind Konstruktionslinien. Der Bezugsstrich bedeutet 10 N. Die Komponenten ersetzen die Gewichtskraft; die Kontakt-Normalkraft ist eine andere Kraft.'),
 'T': ('43b2c500-bbd9-5c92-9f3e-618d310e5690', 'Für einen Körper an einer um 30 Grad zur Waagerechten geneigten Ebene wird die Gewichtskraft 60 N in +30 N hangabwärts und rund −52 N bei positiver Normale nach außen zerlegt. Alle Kraftpfeile beginnen am Körper und verwenden denselben 10-N-Bezugsstrich. Sinus und Kosinus sowie die Grenzfälle bei null und annähernd 90 Grad sind angegeben.'),
 'F': ('3a2accd7-639f-50e1-a7b1-5a9d3c2432a6', 'Zwei getrennte Kontakte mit jeweils 100 N Normalkraft: links passt sich die Haftreibung an 30 N Bedarf an, unterhalb der Grenze 40 N; rechts gleitet der Körper nach rechts und erfährt 25 N Reibung nach links. Die Kraftpfeile beginnen jeweils am betrachteten Körper. Der gemeinsame Kraftmaßstab beträgt 10 N je Bezugsstrich. Bei 40 N ist Haften an der Grenze möglich.'),
 'motion': ('30ddb2d7-b991-55fe-9e74-37ffe1048f9f', 'Ein nach rechts gleitender Körper von 2 kg mit Anfangsgeschwindigkeit +6 m/s berührt eine raue waagerechte Fläche. Sein Reibungspfeil von −4 N beginnt am Körper und zeigt nach links, bei 2 N je Bezugsstrich. Unter konstanter Reibung gelten a = −2 m/s² und v = 6 − 2t ausschließlich bis zum Stillstand nach 3 s. Positive Richtung ist rechts.'),
 'curve': ('e2da5eec-45de-5527-9ad7-16f41cacbe58', 'Draufsicht einer ebenen Kreisfahrt: Am Auto beginnt ein 2000-N-Haftkraftpfeil zum Mittelpunkt M hin und endet frei vor M. Sein Kraftmaßstab beträgt 1000 N je Bezugsstrich. Aus 1000 kg, 10 m/s und 50 m folgen 2000 N benötigte Radialkraft. Die verfügbare maximale Haftkraft ist mit 5000 N gegeben; der Vergleich zeigt mögliches Haften. Ein Reibungskoeffizient wird nicht benötigt.'),
 'given': ('5f289cdc-fda1-4058-b44f-041ba1398e79', 'Ein Wagen von 2 kg hat die gegebene Resultierende +6 N nach rechts. Der Kraftpfeil beginnt am Wagen und entspricht drei 2-N-Bezugsstrichen. Daraus folgt a = +3 m/s². Die positive Richtung ist rechts; bei Resultierender null gilt Beschleunigung null. Ein Beschleunigungspfeil wird nicht gezeichnet.')
}
prompts = json.loads((base/'generation-attempts/prompts.actual.json').read_text())
for key, (goal_id, alt) in specs.items():
 p = base/'sources'/f'{key}-production-prompt.txt'
 generation = prompts['car' if key == 'curve' else 'block']['prompt'] if key != 'given' else '''Use case: scientific-educational. Create a calm friendly hand-drawn German Physics learner illustration, wide 1600x1000-like ratio, warm ivory paper, navy pen and soft teal/yellow pencil. Topic: given resultant force determines acceleration. A single small teal cart rests on a horizontal rail, body centred near x=450 y=450. Put one red force arrow starting at a dark point ON the centre of that cart, horizontally right, labelled 'Fres = +6 N'. The complete arrow from its tail to its tip must be exactly three times as long as the force-scale reference bar. Both ends of the reference bar are vertical ticks, not arrowheads. The only scale legend is 'Kraft · Pfeilmaßstab' and below it the bar labelled '2 N'. No acceleration arrow. Text top: 'Gegebene Resultierende'. Cart text: 'm = 2 kg'. Below large readable text: 'a = Fres / m = +3 m/s²'. Bottom two short lines: 'Positive Richtung: rechts' and 'Fres = 0: a = 0'. Force tip ends freely and points to no object. All type very large and readable at 360px width. Single cart, no people, no decorative sparkles, no emphasis rays, no highlight panels. No other forces or symbols.'''
 p.write_text('Actual image_gen prompt for the final generated drawing ingredient:\n\n'+generation+'\n\nFinal scientific composition (precise-diagram exception after rejected generated force scales):\n'+alt+'\n\nFinal asset is 1600 by 900. The source layout is scaled uniformly, with horizontal safe margins. No force geometry is stretched. Exact source: render-material.mjs and sources/'+key+'.svg. The given-resultant drawing is contained without stretch instead. Actual rejected whole-image generation attempts and their prompt set are retained separately.\n')
 subprocess.run(['node','scripts/prepare_goal_visualization.mjs',goal_id,'--landscape',landscape,'--subject','physik','--provider',provider],check=True)
 subprocess.run(['node','scripts/import_goal_visualization.mjs',goal_id,str(base/'render'/f'{goal_id}.jpg'),'--landscape',landscape,'--subject','physik','--provider',('OpenAI / Codex image_gen' if key=='given' else provider),'--license','CC-BY-4.0','--description',alt,'--alt-text',alt,'--prompt',str(p)],check=True)
(base/'resource-links.actual.json').write_text(json.dumps({'schemaVersion':1,'links':[{**{'key':key,'goalId':gid},'altText':alt} for key,(gid,alt) in specs.items()]},ensure_ascii=False,indent=2)+'\n')
